  function defaultBranches(){return [{id:'PL',name:'Phú Lợi',status:'active',note:'Chi nhánh mặc định'},{id:'NQ',name:'Ngô Quyền',status:'active',note:'Chi nhánh mặc định'},{id:'LT',name:'Lái Thiêu',status:'active',note:'Chi nhánh mặc định'}]}
