  function normalizePositionName(name,department){var n=trim(name).replace(/\s+/g,' ');if(!n)return'';var key=n.toLowerCase().replace(/\s*\/\s*/g,'/');if(key==='quản lý/trưởng ca'||key==='quan ly/truong ca')return String(department||'').toLowerCase().indexOf('bán hàng')>=0?'Trưởng ca':'Quản lý';if(key==='nhân viên'||key==='nhan vien')return'Nhân viên';if(/^trưởng bộ phận\s+/i.test(n))return'Trưởng bộ phận '+shortDeptName(n.replace(/^Trưởng bộ phận\s+/i,''));return n.replace(/TRƯỞNG CA/g,'Trưởng ca').replace(/NHÂN VIÊN/g,'Nhân viên')}
  function inferPositionLevel(name){var n=String(name||'').toLowerCase();if(n.indexOf('trưởng bộ phận')===0)return'TBP';if(n.indexOf('trưởng ca')>=0||n.indexOf('cửa hàng trưởng')>=0||n.indexOf('quản lý')>=0||n.indexOf('giám đốc')>=0)return'Quản lý';return'Nhân viên'}
  function defaultPositions(){var deps=defaultDepartments(), out=[];deps.forEach(function(d){var names=uniq(staff().filter(function(s){return String(s.department||'').toLowerCase()===String(d.name||'').toLowerCase()}).map(function(s){return normalizePositionName(s.position,d.name)}));if(!isBoardDepartment(d.name)){var tbp='Trưởng bộ phận '+shortDeptName(d.name);if(names.map(function(x){return x.toLowerCase()}).indexOf(tbp.toLowerCase())<0)names.push(tbp)}names.forEach(function(n){if(!n)return;var level=inferPositionLevel(n);out.push(makeItem('POS_'+slug(d.name+'_'+n),n,{department:d.name,level:level,isManager:level!=='Nhân viên',status:'active',note:'Vị trí công việc theo phòng ban'}))});});return out}
