  function accountBulkProtected(a){var email=cleanEmail(a&&a.email);return email===currentLoginEmail()||email===ROOT_ADMIN_EMAIL||(isWebOperatorUi()&&(String(a&&a.role||'').toLowerCase()==='admin'||String(a&&a.accountType||'').toLowerCase()==='system_admin'))}
