  function accountBulkUpdateUi(){var count=accountBulkSelection().length,el=document.getElementById('phfAcctBulkCount'),bar=document.getElementById('phfAcctBulkBar');if(el)el.textContent=String(count);if(bar)bar.classList.toggle('active',count>0);var all=document.getElementById('phfAcctBulkAll'),boxes=Array.prototype.slice.call(document.querySelectorAll('.phf-acct-bulk-check:not(:disabled)'));if(all){all.checked=!!boxes.length&&boxes.every(function(x){return x.checked});all.indeterminate=boxes.some(function(x){return x.checked})&&!all.checked}}
