  function phfHrAssignmentKey(v){return String(v==null?'':v).trim().toLowerCase()}
  function phfHrFindAssignment(account){
    if(!account)return null;
    var keys=[account.employeeId,account.employeeCode].map(phfHrAssignmentKey).filter(Boolean);
    return (PHF_HR_ACCESS_STATE.assignments||[]).find(function(row){
      var rowKeys=[row.employeeKey,row.employeeId,row.employeeCode].map(phfHrAssignmentKey).filter(Boolean);
      return keys.some(function(k){return rowKeys.indexOf(k)>=0});
    })||null;
  }
  function phfHrEmployeeStatusLabel(row,account){
    if(account&&account.accountType==='system_admin')return 'Tài khoản hệ thống';
    return String(row&&row.employeeStatus||'Chưa đồng bộ').trim()||'Chưa đồng bộ';
  }
  function phfHrChecklistStatus(row,account){
    if(account&&account.accountType==='system_admin')return{label:'Quản trị hệ thống',tone:'blue'};
    if(!row)return{label:'Chưa có cấu hình',tone:'muted'};
    var status=String(row.employeeStatus||'Đang làm việc').trim();
    if(status==='Đã nghỉ việc')return{label:'Ngừng áp dụng',tone:'muted'};
    if(status==='Nghỉ dài hạn')return{label:'Tạm dừng',tone:'warn'};
    return{label:row.templateId?'Đang hoạt động':'Chưa gán mẫu',tone:row.templateId?'green':'warn'};
  }
  function phfHrAccessWarnings(account,row){
    var warnings=[];
    if(account.accountType!=='system_admin'&&!account.employeeId)warnings.push('Tài khoản chưa liên kết hồ sơ');
    var employeeStatus=String(row&&row.employeeStatus||'').trim();
    if(employeeStatus==='Đã nghỉ việc'&&account.status==='active')warnings.push('Đã nghỉ việc nhưng tài khoản còn hoạt động');
    if(employeeStatus==='Nghỉ dài hạn'&&account.status==='active')warnings.push('Nghỉ dài hạn nhưng tài khoản chưa tạm khóa');
    if(employeeStatus==='Đã nghỉ việc'&&account.hubAssignmentStatus==='active')warnings.push('Hub vẫn đang ở trạng thái Đang học');
    if(!row&&account.accountType!=='system_admin')warnings.push('Chưa có cấu hình Checklist');
    return warnings;
  }
  function phfHrAccessSummary(account){
    var row=phfHrFindAssignment(account),check=phfHrChecklistStatus(row,account),warnings=phfHrAccessWarnings(account,row);
    var employeeStatus=phfHrEmployeeStatusLabel(row,account);
    var classroom=account.accountType==='system_admin'?'Quản trị':(account.status!=='active'?'Không truy cập':(account.defaultProgram==='new_sales'||account.defaultProgram==='phf_class'?'Đang tham gia':'Chưa kích hoạt'));
    return{row:row,employeeStatus:employeeStatus,checklist:check,warnings:warnings,classroom:classroom};
  }
