  async function phfHrLoadAccessState(force){
    if(PHF_HR_ACCESS_STATE.loading)return;
    if(PHF_HR_ACCESS_STATE.ready&&!force&&Date.now()-PHF_HR_ACCESS_STATE.loadedAt<30000)return;
    PHF_HR_ACCESS_STATE.loading=true;
    try{
      var response=await fetch('/api/data?checklistAssignments=1',{method:'GET',credentials:'same-origin',cache:'no-store',headers:{'Accept':'application/json'}});
      var data=await response.json().catch(function(){return{}});
      if(!response.ok)throw new Error(data.error||'Không tải được trạng thái Checklist.');
      PHF_HR_ACCESS_STATE.assignments=Array.isArray(data.checklistAssignments)?data.checklistAssignments:[];
      PHF_HR_ACCESS_STATE.ready=!!data.checklistAssignmentsReady;
      PHF_HR_ACCESS_STATE.error=data.checklistAssignmentsError||'';
      PHF_HR_ACCESS_STATE.loadedAt=Date.now();
      refreshAccounts();
    }catch(error){PHF_HR_ACCESS_STATE.error=error&&error.message||'Không tải được trạng thái Checklist.';}
    finally{PHF_HR_ACCESS_STATE.loading=false}
  }
