          var assignment=Object.assign({},row,{employeeKey:row.employeeKey||account.employeeCode||account.employeeId,employeeId:row.employeeId||account.employeeId||'',employeeCode:row.employeeCode||account.employeeCode||'',employeeName:row.employeeName||account.name||'',department:row.department||account.department||'',title:row.title||account.position||'',branch:row.branch||account.branch||'',employeeStatus:checklistSelect.value,effectiveDate:new Date().toISOString().slice(0,10),reason:'Cập nhật truy cập từ Quản trị tài khoản PHF HR'});
          var saveResponse=await fetch('/api/data?checklistAssignments=1',{method:'POST',credentials:'same-origin',cache:'no-store',headers:{'Content-Type':'application/json','Accept':'application/json'},body:JSON.stringify({action:'saveChecklistAssignments',assignments:[assignment]})});
          var saveData=await saveResponse.json().catch(function(){return{}});if(!saveResponse.ok)throw new Error(saveData.error||'Không lưu được trạng thái Checklist.');
