  function suspectReasons(a){var out=[],email=cleanEmail(a&&a.email),name=String(a&&a.name||'').toLowerCase(),note=String(a&&a.note||'').toLowerCase(),id=String(a&&a.id||'').toLowerCase();if(email.indexOf('@phf.local')>=0)out.push('Tên miền thử nghiệm');if(/(^|[._-])test([._-]|$)/.test(email)||name.indexOf('test')>=0||note.indexOf('test')>=0||id.indexOf('test')>=0)out.push('Có dấu hiệu “test”');if(name.indexOf('demo')>=0||note.indexOf('demo')>=0||id.indexOf('demo')>=0)out.push('Có dấu hiệu “demo”');if(name.indexOf('mẫu')>=0||name.indexOf('mau')>=0||note.indexOf('mẫu')>=0||note.indexOf('mau')>=0)out.push('Có dấu hiệu dữ liệu mẫu');return out}
