      root.innerHTML='<section class="phf-modal-card phf-credential-card" role="dialog" aria-modal="true"><div class="phf-modal-head"><button class="phf-modal-close" type="button" id="phfResetCloseTop" aria-label="Đóng">×</button><div class="phf-modal-icon">✓</div><div><h3>Đã cấp lại mật khẩu</h3><p>Mật khẩu cũ đã ngừng sử dụng. Mật khẩu tạm chỉ hiển thị trong lần này.</p></div></div><div class="phf-credential-body"><dl><div><dt>Họ tên</dt><dd>'+esc(account.name||'—')+'</dd></div><div><dt>Tài khoản</dt><dd>'+esc(account.email||'—')+'</dd></div><div><dt>Trạng thái</dt><dd>Cần đổi mật khẩu</dd></div></dl><div class="phf-credential-secret"><span>Mật khẩu tạm mới</span><strong>'+esc(temp||'')+'</strong></div><p class="phf-credential-note">Sau khi đóng cửa sổ này, hệ thống không thể xem lại mật khẩu. Nếu thất lạc, Admin cần cấp lại một mật khẩu khác.</p></div><div class="phf-modal-actions"><button class="phf-modal-btn" id="phfResetCopyTemp">Sao chép mật khẩu</button><button class="phf-modal-btn" id="phfResetCopyAll">Sao chép thông tin</button><button class="phf-modal-btn primary" id="phfResetClose">Đóng</button></div></section>';
      document.body.appendChild(root);
      root.querySelector('#phfResetCopyTemp').onclick=async function(){await copyText(temp);this.textContent='Đã sao chép'};
      root.querySelector('#phfResetCopyAll').onclick=async function(){await copyText(full);this.textContent='Đã sao chép'};
      function closeReset(){root.remove();resolve(true)};root.querySelector('#phfResetClose').onclick=closeReset;root.querySelector('#phfResetCloseTop').onclick=closeReset;
